class Solution {
  public int superpalindromesInRange(String left, String right) {
    long lo = Long.parseLong(left), hi = Long.parseLong(right);
    int ans = 0;
    // a super-palindrome is the square of a palindrome; the range reaches 10^18, so roots go up to 10^9
    for (int p = 1; p < 100000; p++) {
      String s = String.valueOf(p);
      String rev = new StringBuilder(s).reverse().toString();
      for (String t : new String[] {s + rev, s + rev.substring(1)}) {
        long x = Long.parseLong(t);
        if (x > 1_000_000_000L) continue;
        long square = x * x;
        if (square >= lo && square <= hi && isPal(square)) ans++;
      }
    }
    return ans;
  }

  private boolean isPal(long x) {
    String s = Long.toString(x);
    return s.equals(new StringBuilder(s).reverse().toString());
  }
}
